    faqQ1: "क्या डेटा वास्तव में क्लाइंट-साइड एन्क्रिप्टेड है?",
    faqA1: "हाँ। लॉगबुक प्लस के अंदर लॉग किया गया सारा डेटा कैश या सिंक होने से पहले एईएस-256 ब्लॉक साइफर का उपयोग करके स्थानीय रूप से एन्क्रिप्ट किया जाता है। आपकी निजी कुंजी पासफ़्रेज़ के बिना, कोई भी (हमारे बुनियादी ढांचे प्रदाताओं या डेवलपर्स सहित) आपके रिकॉर्ड को नहीं पढ़ सकता है।",
    faqQ2: "यदि मैं अपनी प्रीमियम सदस्यता रद्द कर दूँ तो क्या होगा?",
    faqA2: "यदि आप अपनी सदस्यता रद्द करते हैं, तो आप अपनी सभी प्रविष्टियों तक स्थानीय पहुंच बनाए रखेंगे। हमारे क्लाउड वॉल्ट पर आपके बैकअप आपके बिलिंग चक्र के अंत तक सक्रिय रहेंगे। समाप्ति के बाद, हम आपके वॉल्ट बैकअप को सुरक्षित रूप से हटाए जाने से पहले डाउनलोड करने के लिए 30 दिनों की छूट अवधि प्रदान करते हैं।",
    faqQ3: "स्व-होस्टेड मास्टर लाइसेंस कैसे काम करता है?",
    faqA3: "स्व-होस्टेड मास्टर लाइसेंस आपको अपने स्वयं के सर्वर हार्डवेयर (जैसे डॉकर, नोड.जेएस, वेबडीएवी के माध्यम से) पर लॉगबुक बैकअप लक्ष्य कंसोल चलाने के लिए एक स्थायी, रॉयल्टी-मुक्त कुंजी देता है। यह पूर्ण एन्क्रिप्टेड सिंक कार्यक्षमता बनाए रखते हुए हमारे क्लाउड सर्वर को पूरी तरह से बायपास करता है।",

