    faqA1: "হ্যাঁ। লগবুক প্লাসের ভিতরে লগ করা সমস্ত ডেটা ক্যাশে বা সিঙ্ক করার আগে স্থানীয়ভাবে AES-256 ব্লক সাইফার ব্যবহার করে এনক্রিপ্ট করা হয়। আপনার ব্যক্তিগত কী পাসফ্রেজ ছাড়া, কেউ (আমাদের অবকাঠামো প্রদানকারী বা বিকাশকারী সহ) আপনার রেকর্ড পড়তে পারবে না।",
