    faqA2: "আপনি যদি আপনার সদস্যতা বাতিল করেন, আপনি আপনার সমস্ত এন্ট্রিতে স্থানীয় অ্যাক্সেস বজায় রাখবেন। আমাদের ক্লাউড ভল্টে আপনার ব্যাকআপগুলি আপনার বিলিং চক্রের শেষ না হওয়া পর্যন্ত সক্রিয় থাকবে৷ মেয়াদ শেষ হওয়ার পরে, আমরা আপনার ভল্ট ব্যাকআপ ডাউনলোড করার জন্য একটি 30-দিনের গ্রেস পিরিয়ড প্রদান করি এটি নিরাপদে পরিষ্কার করার আগে।",
    faqQ3: "স্ব-হোস্টেড মাস্টার লাইসেন্স কিভাবে কাজ করে?",
    faqA3: "স্ব-হোস্টেড মাস্টার লাইসেন্স আপনাকে আপনার নিজস্ব সার্ভার হার্ডওয়্যারে (যেমন ডকার, Node.js, WebDAV এর মাধ্যমে) লগবুক ব্যাকআপ টার্গেট কনসোল চালানোর জন্য একটি চিরস্থায়ী, রয়্যালটি-মুক্ত কী দেয়। সম্পূর্ণ এনক্রিপ্টেড সিঙ্ক কার্যকারিতা বজায় রেখে এটি আমাদের ক্লাউড সার্ভারগুলিকে সম্পূর্ণভাবে বাইপাস করে।",
