    philosophySubtitle: "நவீன காப்புப்பிரதி வசதிக்காக உங்கள் நிதி தனியுரிமையை நீங்கள் விட்டுக்கொடுக்க வேண்டியதில்லை என்ற எளிய நம்பிக்கையில் லாக்புக் பிளஸ் நிறுவப்பட்டது. உங்கள் பதிவுகளை முழுமையாக வைத்திருக்க உதவும் உள்ளூர்-முதல் கருவிகளை நாங்கள் உருவாக்குகிறோம்.",
