    bentoOfflineFirst: "முதலில் ஆஃப்லைன்",
    bentoPrivacyDesc: "டெலிமெட்ரி இல்லை. பின்னணி டிராக்கர்கள் இல்லை. Logbook Plus உங்கள் உலாவி அல்லது சொந்த பணியிடத்தில் உள்ள உள்ளூர் தரவுத்தளத்தில் தரவை நேரடியாகச் சேமிக்கிறது. எங்களின் கிளவுட் சர்வர் செயலிழந்தாலும், உங்கள் மென்பொருள் சரியாகவே செயல்படுகிறது.",
