    bentoRapidTitle: "விரைவான நுழைவு இயந்திரம்",
    bentoRapidDesc: "விசைப்பலகை குறுக்குவழிகள் மூலம் பரிவர்த்தனைகள், பதிவுகள் மற்றும் வகைகளை பதிவு செய்யவும். துணை-10ms UI பெயிண்ட் வேகம்.",
    bentoQuickLog: "விரைவான பதிவு பதிவு",
    bentoInsightsTitle: "ஊடாடும் நுண்ணறிவு",
    bentoInsightsDesc: "நிகழ்நேரத்��ில் பதிவுகளை வடிகட்டவும், வெட்டவும் மற்றும் மதிப்பாய்வு செய்யவும். விளக்கப்படக் கணக்கீடுகள் கிளையன்ட் பக்கமாக கணக்கிடப்படுகின்றன, API பெறுதல்கள் இல்லாமல் உடனடி தளவமைப்புகளை வழங்கும்.",
    bentoSecurityTitle: "ஜீரோ-அறிவு பாதுகாப்பு",
    bentoSecurityDesc: "அனைத்து காப்புப்பிரதிகளும் பதிவேற்றும் முன் உங்கள் SHA-256 ஹாஷ் செய்யப்பட்ட தனிப்பட்ட விசையுடன் குறியாக்கம் செய்யப்பட்டுள்ளன. எங்கள் சர்வர் நிர்வாகிகள் எந்த சூழ்நிலையிலும் உங்கள் கோப்புகளை படிக்கவோ, டிகோட் செய்யவோ அல்லது பகுப்பாய்வு செய்யவோ முடியாது.",
    valuePrivacyTitle: "முழுமையான தனியுரிமை",
    valuePrivacyDesc: "டெலிமெட்ரி இல்லை, டிராக்கிங் ஸ்கிரிப்டுகள் இல்லை மற்றும் ரகசிய பகுப்பாய்வு கண்காணிப்பு இல்லை. நீங்கள் Logbook Plus இல் உள்நுழைவது உங்களுக்கும் உங்கள் சாதனத்திற்கும் இடையில் இருக்கும்.",
    valueCloudTitle: "கிளவுட் பாதுகாப்பு",
    valueCloudDesc: "தடையற்ற காப்பு தானாக ஒத்திசைவு. எங்கள் கிளையன்ட் பக்க மறைகுறியாக்கப்பட்ட கிளவுட் வால்ட்களில் உங்கள் பதிவுகளை காப்புப் பிரதி எடுக்கவும், முழுமையான முக்கிய கட்டுப்பாட்டை நீங்கள் பராமரிக்கிறீர்கள் என்பதை உறுதிப்படுத்துகிறது.",
    valueLocalTitle: "உள்ளூர் முதல் தரவு",
    valueLocalDesc: "உங்கள் அளவீடுகளை ஏற்றுவதற்கு தொலை சேவையகத்தை ஒருபோதும் நம்ப வேண்டாம். எல்லா பதிவுகளும் சாதனத்தில் உள்ளூரில் சேமிக்கப்பட்டு ஆஃப்லைனிலும் உடனடியாக ஏற்றப்படும்.",
    architecturalCreed: "எங்கள் கட்டிடக்கலை நம்பிக்கை",
    creedDesc1: "நவீன தரவு அறுவடை வணிக மாதிரியை நாங்கள் நிராகரிக்கிறோம். பெரும்பாலான நிதிப் பயன்பாடுகள் உங்கள் பரிவர்த்தனைகளை கிரெடிட் தரகர்களுக்கு அலசுகின்றன மற்றும் விற்கின்றன. Logbook Plus வலுவான கிளையன்ட் பக்க AES-256 குறியாக்கத்தைப் பயன்படுத்துகிறது, அதாவது உங்கள் பதிவுக���் எப்போதும் ஒத்திசைக்கப்படுவதற்கு முன்பே அவை கணித ரீதியாக பாதுகாப்பானவை.",
    creedDesc2: "நீங்கள் தினசரி ரசீதுகளை ஒழுங்கமைத்தாலும், வாராந்திர திட்டக் கணக்குகளை நிர்வகித்தாலும் அல்லது மாதாந்திர அறிக்கைகளை ஏற்றுமதி செய்தாலும், நீங்கள் முழுமையான கட்டளையில் இருக்கிறீர்கள்.",
    creedItem1: "துணை மில்லிசெகண்ட் மறுமொழி நேரங்களைக் கொண்ட உள்ளூர் தரவுத்தளம்",
    creedItem2: "முழுமையாக தனிப்பயனாக்கக்கூடிய சேமிப்புக் கொள்கை கட்டமைப்புகள் (தினசரி, வாராந்திர, மாதாந்திர)",
