    faqQ1: "தரவு உண்மையில் கிளையன்ட் பக்க குறியாக்கம் செய்யப்பட்டதா?",
    faqA1: "ஆம். லாக்புக் பிளஸில் உள்நுழைந்துள்ள எல்லாத் தரவும், தற்காலிகச் சேமிப்பு அல்லது ஒத்திசைக்கப்படுவதற்கு முன், AES-256 தொகுதி மறைக்குறியீட்டைப் பயன்படுத்தி உள்நாட்டில் குறியாக்கம் செய்யப்படுகிறது. உங்கள் தனிப்பட்ட விசைக் கடவுச்சொற்றொடரை இல்லாமல், யாரும் (எங்கள் உள்கட்டமைப்பு வழங்குநர்கள் அல்லது டெவலப்பர்கள் உட்பட) உங்கள் பதிவுகளைப் படிக்க முடியாது.",
    faqQ2: "எனது பிரீமியம் சந்தாவை ரத்து செய்தால் என்ன ஆகும்?",
    faqA2: "உங்கள் சந்தாவை ரத்து செய்தால், உங்கள் எல்லா உள்ளீடுகளுக்கும் உள்ளூர் அணுகலைத் தக்கவைத்துக் கொள்வீர்கள். உங்கள் பில்லிங் சுழற்சி முடியும் வரை எங்கள் கிளவுட் வால்ட்டில் உள்ள காப்புப் பிரதிகள் செயலில் இருக்கும். காலாவதியான பிறகு, உங்கள் வால்ட் காப்புப்பிரதியை பாதுகாப்பாக சுத்தப்படுத்துவதற்கு முன் அதைப் பதிவிறக்குவதற்கு 30 நாள் அவகாசம் வழங்குகிறோம்.",
    faqQ3: "சுய-ஹோஸ்ட் செய்யப்பட்ட முதன்மை உரிமம் எவ்வாறு செயல்படுகிறது?",
    faqA3: "உங்கள் சொந்த சேவையக வன்பொருளில் (எ.கா. Docker, Node.js, WebDAV வழியாக) லாக்புக் காப்பு இலக்கு கன்சோலை இயக்க சுய-ஹோஸ்ட் செய்யப்பட்ட முதன்மை உரிமம் நிரந்தரமான, ராயல்டி இல்லாத விசையை வழங்குகிறது. முழு மறைகுறியாக்கப்பட்ட ஒத்திசைவு செயல்பாட்டைப் பராமரிக்கும் போது இது எங்கள் கிளவுட் சேவையகங்களை முற்றிலும் புறக்கணிக்கிறது.",
