    valueLocalDesc: "మీ కొలమానాలను లోడ్ చేయడానికి రిమోట్ సర్వర్‌పై ఎప్పుడూ ఆధారపడకండి. అన్ని రికార్డులు పరికరంలో స్థానికంగా నిల్వ చేయబడతాయి మరియు ఆఫ్‌లైన్‌లో కూడా తక్షణమే లోడ్ అవుతాయి.",
    architecturalCreed: "మా ఆర్కిటెక్చరల్ క్రీడ్",
    creedDesc1: "మేము ఆధునిక డేటా హార్వెస్టింగ్ వ్యాపార నమూనాను తిరస్కరించాము. చాలా ఆర్థిక అప్లికేషన్‌లు మీ లావాదేవీలను క్రెడిట్ బ్రోకర్‌లకు అన్వయించి విక్రయిస్తాయి. లాగ్‌బుక్ ప్లస్ బలమైన క్లయింట్ వైపు AES-256 ఎన్‌క్రిప్షన్‌ను ఉపయోగిస్తుంది, అంటే మీ లాగ్‌లు సమకాలీకరించకముందే గణితశాస్త్రపరంగా సురక్షితంగా ఉంటాయి.",
    creedDesc2: "మీరు రోజువారీ రసీదులను ఆర్గనైజ్ చేసినా, వీక్లీ ప్రాజెక్ట్ ఖాతాలను నిర్వహిస్తున్నా లేదా నెలవారీ స్టేట్‌మెంట్‌లను ఎగుమతి చేసినా, మీరు పూర్తి ఆదేశాన్ని కలిగి ఉంటారు.",
    creedItem1: "ఉప-మిల్లీసెకన్ల ప్రతిస్పందన సమయాలతో స్థానిక డేటాబేస్",
    creedItem2: "పూర్తిగా అనుకూలీకరించదగిన నిల్వ విధాన నిర్మాణాలు (రోజువారీ, వారం, నెలవారీ)",
    creedItem3: "అతుకులు లేని టోకెన్ ఆధారిత అడ్మినిస్ట్రేటివ్ సింక్ మానిటరింగ్",
    creedItem4: "సురక్షిత ప్రశ్న ధృవీకరణలను ఉపయోగించి ఒక-క్లిక్ పూర్తి పునరుద్ధరణ",
