    faqHeader: "తరచుగా అడిగే ప్రశ్నలు",
    faqQ1: "డేటా నిజంగా క్లయింట్ వైపు ఎన్‌క్రిప్ట్ చేయబడిందా?",
    faqA1: "అవున��. లాగ్‌బుక్ ప్లస్‌లో లాగిన్ చేసిన మొత్తం డేటా కాష్ లేదా సింక్ చేయడానికి ముందు AES-256 బ్లాక్ సైఫర్‌ని ఉపయోగించి స్థానికంగా గుప్తీకరించబడుతుంది. మీ ప్రైవేట్ కీ పాస్‌ఫ్రేజ్ లేకుండా, ఎవరూ (మా ఇన్‌ఫ్రాస్ట్రక్చర్ ప్రొవైడర్‌లు లేదా డెవలపర్‌లతో సహా) మీ రికార్డ్‌లను చదవలేరు.",
    faqQ2: "నేను నా ప్రీమియం సభ్యత్వాన్ని రద్దు చేస్తే ఏమి జరుగుతుంది?",
    faqA2: "మీరు మీ సభ్యత్వాన్ని రద్దు చేస్తే, మీరు మీ అన్ని ఎంట్రీలకు స్థానిక యాక్సెస్‌ను కలిగి ఉంటారు. మా క్లౌడ్ వాల్ట్‌లోని మీ బ్యాకప్‌లు మీ బిల్లింగ్ సైకిల్ ముగిసే వరకు సక్రియంగా ఉంటాయి. గడువు ముగిసిన తర్వాత, సురక్షితంగా ప్రక్షాళన చేయబడే ముందు మీ వాల్ట్ బ్యాకప్‌ని డౌన్‌లోడ్ చేయడానికి మేము 30-రోజుల గ్రేస్ పీరియడ్‌ని అందిస్తాము.",
    faqQ3: "స్వీయ-హోస్ట్ చేసిన మాస్టర్ లైసెన్స్ ఎలా పని చేస్తుంది?",
    faqA3: "మీ స్వంత సర్వర్ హార్డ్‌వేర్‌లో (ఉదా. డాకర్, Node.js, WebDAV ద్వారా) లాగ్‌బుక్ బ్యాకప్ టార్గెట్ కన్సోల్‌ను అమలు చేయడానికి స్వీయ-హోస్ట్ చేసిన మాస్టర్ లైసెన్స్ మీకు శాశ్వతమైన, రాయల్టీ రహిత కీని అందిస్తుంది. ఇది పూర్తి ఎన్‌క్రిప్టెడ్ సింక్ ఫంక్షనాలిటీని కొనసాగిస్తూనే మా క్లౌడ్ సర్వర్‌లను పూర్తిగా దాటవేస్తుంది.",
    securityQuestion1: "మీ మొదటి పెంపుడు జంతువు పేరు ఏమిటి?",
    securityQuestion2: "మీ తల్లి మొదటి పేరు ఏమిటి?",
    securityQuestion3: "మీరు ఏ నగరంలో జన్మించారు?",
