    bentoPrivacyTitle: "100% ಕ್ಲೈಂಟ್-ಸೈಡ್ ಗೌಪ್ಯತೆ",
    bentoOfflineFirst: "ಮೊದಲು ಆಫ್‌ಲೈನ್",
    bentoPrivacyDesc: "ಟೆಲಿಮೆಟ್ರಿ ಇಲ್ಲ. ಹಿನ್ನೆಲೆ ಟ್ರ್ಯಾಕರ್‌ಗಳಿಲ್ಲ. ಲಾಗ್‌ಬುಕ್ ಪ್ಲಸ್ ಡೇಟಾವನ್ನು ನೇರವಾಗಿ ನಿಮ್ಮ ಬ್ರೌಸರ್ ಅಥವಾ ಸ್ಥಳೀಯ ಕಾರ್ಯಸ್ಥಳದಲ್ಲಿ ಸ್ಥಳೀಯ ಡೇಟಾಬೇಸ್‌ಗೆ ಉಳಿಸುತ್ತದೆ. ನಮ್ಮ ಕ್ಲೌಡ್ ಸರ್ವರ್ ಡೌನ್ ಆಗಿದ್ದರೂ, ನಿಮ್ಮ ಸಾಫ್ಟ್‌ವೇರ್ ಒಂದೇ ರೀತಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.",
    bentoSqliteLocal: "SQLite ಸಂಗ್ರಹ (ಸ್ಥಳೀಯ)",
