    bentoQuickLog: "ತ್ವರಿತ ಲಾಗ್ ದಾಖಲೆ",
    bentoInsightsTitle: "ಸಂವಾದಾತ್ಮಕ ಒಳನೋಟಗಳು",
    bentoInsightsDesc: "ನೈಜ ಸಮಯದಲ್ಲಿ ದಾಖಲೆಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ, ಸ್ಲೈಸ್ ಮಾಡಿ ಮತ್ತು ಪರಿಶೀಲಿಸಿ. ಚಾರ್ಟ್ ಲೆಕ್ಕಾಚಾರಗಳು ಕ್ಲೈಂಟ್-ಸೈಡ್ ಅನ್ನು ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ, API ಪಡೆಯುವಿಕೆಗಳಿಲ್ಲದೆ ತಕ್ಷಣದ ಲೇಔಟ್‌ಗಳನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತದೆ.",
    bentoSecurityTitle: "ಶೂನ್ಯ-ಜ್ಞಾನ ಭದ್ರತೆ",
    bentoSecurityDesc: "ಅಪ್‌ಲೋಡ್ ಮಾಡುವ ಮೊದಲು ಎಲ್ಲಾ ಬ್ಯಾಕಪ್‌ಗಳನ್ನು ನಿಮ್ಮ SHA-256 ಹ್ಯಾಶ್ ಮಾಡಿದ ಖಾಸಗಿ ಕೀಲಿಯೊಂದಿಗೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ. ನಮ್ಮ ಸರ್ವರ್ ನಿರ್ವಾಹಕರು ಯಾವುದೇ ಸಂದರ್ಭದಲ್ಲಿ ನಿಮ್ಮ ಫೈಲ್‌ಗಳನ್ನು ಓದಲು, ಡಿಕೋಡ್ ಮಾಡಲು ಅಥವಾ ವಿಶ್ಲೇಷಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
    valuePrivacyTitle: "ಸಂಪೂರ್ಣ ಗೌಪ್ಯತೆ",
    valuePrivacyDesc: "ಟೆಲಿಮೆಟ್ರಿ ಇಲ್ಲ, ಟ್ರ್ಯಾಕಿಂಗ್ ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳಿಲ್ಲ ಮತ್ತು ರಹಸ್ಯ ವಿಶ್ಲೇಷಣಾತ್ಮಕ ಮೇಲ್ವಿಚಾರಣೆ ಇಲ್ಲ. ನೀವು ಲಾಗ್‌ಬುಕ್ ಪ್ಲಸ್ ಲಾಗ್ ಇನ್ ಮಾಡುವುದು ನಿಮ್ಮ ಮತ್ತು ನಿಮ್ಮ ಸಾಧನದ ನಡುವೆ ಇರುತ್ತದೆ.",
    valueCloudTitle: "ಮೇಘ ಭದ್ರತೆ",
    valueCloudDesc: "ತಡೆರಹಿತ ಬ್ಯಾಕಪ್ ಸ್ವಯಂ ಸಿಂಕ್. ನಮ್ಮ ಕ್ಲೈಂಟ್-ಸೈಡ್ ಎನ್‌ಕ್ರಿಪ���ಟ್ ಮಾಡಲಾದ ಕ್ಲೌಡ್ ವಾಲ್ಟ್‌ಗಳಿಗೆ ನಿಮ್ಮ ಲಾಗ್‌ಗಳನ್ನು ಬ್ಯಾಕಪ್ ಮಾಡಿ, ನೀವು ಸಂಪೂರ್ಣ ಕೀ ನಿಯಂತ್ರಣವನ್ನು ನಿರ್ವಹಿಸುತ್ತೀರಿ ಎಂದು ಖಾತ್ರಿಪಡಿಸಿಕೊಳ್ಳಿ.",
    valueLocalTitle: "ಸ್ಥಳೀಯ-ಮೊದಲ ಡೇಟಾ",
    valueLocalDesc: "ನಿಮ್ಮ ಮೆಟ್ರಿಕ್‌ಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ರಿಮೋಟ್ ಸರ್ವರ್ ಅನ್ನು ಎಂದಿಗೂ ಅವಲಂಬಿಸಬೇಡಿ. ಎಲ್ಲಾ ದಾಖಲೆಗಳನ್ನು ಸಾಧನದಲ್ಲಿ ಸ್ಥಳೀಯವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿಯೂ ತಕ್ಷಣ ಲೋಡ್ ಮಾಡಲಾಗುತ್ತದೆ.",
    architecturalCreed: "ನಮ್ಮ ಆರ್ಕಿಟೆಕ್ಚರಲ್ ಕ್ರೀಡ್",
    creedDesc1: "ಆಧುನಿಕ ಡೇಟಾ ಕೊಯ್ಲು ವ್ಯವಹಾರ ಮಾದರಿಯನ್ನು ನಾವು ತಿರಸ್ಕರಿಸುತ್ತೇವೆ. ಹೆಚ್ಚಿನ ಹಣಕಾಸು ಅಪ್ಲಿಕೇಶನ್‌ಗಳು ನಿಮ್ಮ ವಹಿವಾಟುಗಳನ್ನು ಕ್ರೆಡಿಟ್ ಬ್ರೋಕರ್‌ಗಳಿಗೆ ಪಾರ್ಸ್ ಮಾಡುತ್ತವೆ ಮತ್ತು ಮಾರಾಟ ಮಾಡುತ್ತವೆ. ಲಾಗ್‌ಬುಕ್ ಪ್ಲಸ್ ಬಲವಾದ ಕ್ಲೈಂಟ್-ಸೈಡ್ ಎಇಎಸ್-256 ಎನ್‌ಕ್ರಿಪ್ಶನ್ ಅನ್ನು ಬಳಸುತ್ತದೆ, ಅಂದರೆ ನಿಮ್ಮ ಲಾಗ್‌ಗಳು ಸಿಂಕ್ ಆಗ��ವ ಮೊದಲು ಗಣಿತದ ದೃಷ್ಟಿಯಿಂದ ಸುರಕ್ಷಿತವಾಗಿರುತ್ತವೆ.",
    creedDesc2: "ನೀವು ದೈನಂದಿನ ರಸೀದಿಗಳನ್ನು ಆಯೋಜಿಸುತ್ತಿರಲಿ, ಸಾಪ್ತಾಹಿಕ ಪ್ರಾಜೆಕ್ಟ್ ಖಾತೆಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತಿರಲಿ ಅಥವಾ ಮಾಸಿಕ ಹೇಳಿಕೆಗಳನ್ನು ರಫ್ತು ಮಾಡುತ್ತಿರಲಿ, ನೀವು ಸಂಪೂರ್ಣ ಆಜ್ಞೆಯಲ್ಲಿದ್ದೀರಿ.",
    creedItem1: "ಉಪ-ಮಿಲಿಸೆಕೆಂಡ್ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯಗಳೊಂದಿಗೆ ಸ್ಥಳೀಯ ಡೇಟಾಬೇಸ್",
