    faqHeader: "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
    faqQ1: "ಡೇಟಾ ನಿಜವಾಗಿಯೂ ಕ್ಲೈಂಟ್-ಸೈಡ್ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿದೆಯೇ?",
    faqA1: "ಹೌದು. ಲಾಗ್‌ಬುಕ್ ಪ್ಲಸ್‌ನಲ್ಲಿ ಲಾಗ್ ಮಾಡಲಾದ ಎಲ್ಲಾ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುವ ಅಥವಾ ಸಿಂಕ್ ಮಾಡುವ ಮೊದಲು AES-256 ಬ್ಲಾಕ್ ಸೈಫರ್ ಅನ್ನು ಬಳಸಿಕೊಂಡು ಸ್ಥಳೀಯವಾಗಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಖಾಸಗಿ ಕೀ ಪಾಸ್‌ಫ್ರೇಸ್ ಇಲ್ಲದೆ, ಯಾರೂ (ನಮ್ಮ ಮೂಲಸೌಕರ್ಯ ಪೂರೈಕೆದಾರರು ಅಥವಾ ಡೆವಲಪರ್‌ಗಳು ಸೇರಿದಂತೆ) ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ಓದಲಾಗುವುದಿಲ್ಲ.",
    faqQ2: "ನನ್ನ ಪ್ರೀಮಿಯಂ ಚಂದಾದಾರಿಕೆಯನ್ನು ನಾನು ರದ್ದುಗೊಳಿಸಿದರೆ ಏನಾಗುತ್ತದೆ?",
    faqA2: "ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಯನ್ನು ನೀವು ರದ್ದುಗೊಳಿಸಿದರೆ, ನಿಮ್ಮ ಎಲ್ಲಾ ನಮೂದುಗಳಿಗೆ ನೀವು ಸ್ಥಳೀಯ ಪ್ರವೇಶವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತೀರಿ. ನಮ್ಮ ಕ್ಲೌಡ್ ವಾಲ್ಟ್‌ನಲ್ಲಿನ ನಿಮ್ಮ ಬ್ಯಾಕಪ್‌ಗಳು ನಿಮ್ಮ ಬಿಲ್ಲಿಂಗ್ ಸೈಕಲ್‌ನ ಕೊನೆಯವರೆಗೂ ಸಕ್ರಿಯವಾಗಿರುತ್ತವೆ. ಅವಧಿ ಮುಗಿದ ನಂತರ, ಸುರಕ್ಷಿತವಾಗಿ ಶುದ್ಧೀಕರಿಸುವ ಮೊದಲು ನಿಮ್ಮ ವಾಲ್ಟ್ ಬ್ಯಾಕಪ್ ಅನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಲು ನಾವು 30-ದಿನಗಳ ಗ್ರೇಸ್ ಅವಧಿಯನ್ನು ಒದಗಿಸುತ್ತೇವೆ.",
    faqQ3: "ಸ್ವಯಂ ಹೋಸ್ಟ್ ಮಾಡಿದ ಮಾಸ್ಟರ್ ಲೈಸೆನ್ಸ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?",
    faqA3: "ನಿಮ್ಮ ಸ್ವಂತ ಸರ್ವರ್ ಹಾರ್ಡ್‌ವೇರ್‌ನಲ್ಲಿ ಲಾಗ್‌ಬುಕ್ ಬ್ಯಾಕಪ್ ಗುರಿ ಕನ್ಸೋಲ್ ಅನ್ನು ಚಲಾಯಿಸಲು ಸ್ವಯಂ-ಹೋಸ್ಟ್ ಮಾಡಿದ ಮಾಸ್ಟರ್ ಲೈಸೆನ್ಸ್ ನಿಮಗೆ ಶಾಶ್ವತವಾದ, ರಾಯಲ್ಟಿ-ಮುಕ್ತ ಕೀಲಿಯನ್ನು ನೀಡುತ್ತದೆ (ಉದಾ. ಡಾಕರ್, Node.js, WebDAV ಮೂಲಕ). ಪೂರ್ಣ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ ಸಿಂಕ್ ಕಾರ್ಯವನ್ನು ನಿರ್ವಹಿಸುವಾಗ ಇದು ನಮ್ಮ ಕ್ಲೌಡ್ ಸರ್ವರ್‌ಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಬೈಪಾಸ್ ಮಾಡುತ್ತದೆ.",
