    philosophySubtitle: "ലോഗ്ബുക്ക് പ്ലസ് സ്ഥാപിക്കപ്പെട്ടത് ഒരു ലളിതമായ വിശ്വാസത്തിലാണ്: ആധുനിക ബാക്കപ്പ് സൗകര്യത്തിനായി നിങ്ങളുടെ സാമ്പത്തിക സ്വകാര്യത പണയം വയ്ക്കേണ്ടതില്ല. നിങ്ങളുടെ ലോഗുകൾ പൂർണ്ണമായും സ്വന്തമാക്കാൻ അനുവദിക്കുന്ന പ്രാദേശിക-ആദ്യ ടൂളുകൾ ഞങ്ങൾ നിർമ്മിക്കുന്നു.",
    sovereigntyShield: "പരമാധികാര ഷീൽഡ്",
