    bentoOfflineFirst: "ആദ്യം ഓഫ്‌ലൈൻ",
    bentoPrivacyDesc: "ടെലിമെട്രി ഇല്ല. പശ്ചാത്തല ട്രാക്കറുകൾ ഇല്ല. ലോഗ്ബുക്ക് പ്ലസ് നിങ്ങളുടെ ബ്രൗസറിലോ നേറ്റീവ് വർക്ക്‌സ്‌പെയ്‌സിലോ ഉള്ള ഒരു പ്രാദേശിക ഡാറ്റാബേസിലേക്ക് നേരിട്ട് ഡാറ്റ സംരക്ഷിക്കുന്നു. ഞങ്ങളുടെ ക്ലൗഡ് സെർവർ പ്രവർത്തനരഹിതമാണെങ്കിൽപ്പോലും, നിങ്ങളുടെ സോഫ്‌റ്റ്‌വെയർ ഒരേപോലെ പ്രവർത്തിക്കുന്നു.",
