    bentoRapidTitle: "റാപ്പിഡ് എൻട്രി എഞ്ചിൻ",
    bentoRapidDesc: "കീബോർഡ് കുറുക്കുവഴികൾ ഉപയോഗിച്ച് ഇടപാടുകൾ, ലോഗുകൾ, വിഭാഗങ്ങൾ എന്നിവ രേഖപ്പെടുത്തുക. സബ്-10ms UI പെയിൻ്റ് വേഗത.",
    bentoQuickLog: "ദ്രുത ലോഗ് റെക്കോർഡ്",
    bentoInsightsTitle: "സംവേദനാത്മക സ്ഥിതിവിവരക്കണക��കുകൾ",
    bentoInsightsDesc: "തത്സമയം റെക്കോർഡുകൾ ഫിൽട്ടർ ചെയ്യുക, സ്ലൈസ് ചെയ്യുക, അവലോകനം ചെയ്യുക. ചാർട്ട് കണക്കുകൂട്ടലുകൾ ക്ലയൻ്റ്-സൈഡ് കണക്കാക്കുന്നു, API ലഭ്യമാക്കാതെ ഉടനടി ലേഔട്ടുകൾ നൽകുന്നു.",
    bentoSecurityTitle: "സീറോ നോളജ് സെക്യൂരിറ്റി",
    bentoSecurityDesc: "അപ്‌ലോഡ് ചെയ്യുന്നതിനുമുമ്പ് എല്ലാ ബാക്കപ്പുകളും നിങ്ങളുടെ SHA-256 ഹാഷ് ചെയ്ത സ്വകാര്യ കീ ഉപയോഗിച്ച് എൻക്രിപ്റ്���് ചെയ്തിരിക്കുന്നു. ഞങ്ങളുടെ സെർവർ അഡ്മിനിസ്ട്രേറ്റർക്ക് ഒരു സാഹചര്യത്തിലും നിങ്ങളുടെ ഫയലുകൾ വായിക്കാനോ ഡീകോഡ് ചെയ്യാനോ വിശകലനം ചെയ്യാനോ കഴിയില്ല.",
    valuePrivacyTitle: "സമ്പൂർണ്ണ സ്വകാര്യത",
    valuePrivacyDesc: "ടെലിമെട്രിയോ ട്രാക്കിംഗ് സ്ക്രിപ്റ്റുകളോ രഹസ്യ വിശകലന നിരീക്ഷണമോ ഇല്ല. നിങ്ങൾ ലോഗ്ബുക്ക് പ്ലസ് ലോഗിൻ ചെയ്യുന്നത് നിങ്ങൾക്കും നിങ്ങളുടെ ഉപകരണത്തിനുമിടയിൽ നിലനിൽക്കും.",
    valueCloudTitle: "ക്ലൗഡ് സുരക്ഷ",
    valueCloudDesc: "തടസ്സമില്ലാത്ത ബാക്കപ്പ് യാന്ത്രിക സമന്വയം. ഞങ്ങള��ടെ ക്ലയൻ്റ് സൈഡ് എൻക്രിപ്റ്റ് ചെയ്ത ക്ലൗഡ് നിലവറകളിലേക്ക് നിങ്ങളുടെ ലോഗുകൾ ബാക്കപ്പ് ചെയ്യുക, നിങ്ങൾ സമ്പൂർണ്ണ കീ നിയന്ത്രണം നിലനിർത്തുന്നുവെന്ന് ഉറപ്പാക്കുക.",
    valueLocalTitle: "പ്രാദേശിക-ആദ്യ ഡാറ്റ",
    valueLocalDesc: "നിങ്ങളുടെ മെട്രിക്‌സ് ലോഡുചെയ്യാൻ ഒരിക്കലും റിമോട്ട് സെർവറിനെ ആശ്രയിക്കരുത്. എല്ലാ റെക്കോർഡുകളും ഉപകരണത്തിൽ പ്രാദേശികമായി സംഭരിക്കുകയും ഓഫ്‌ലൈനിൽ പോലും തൽക്ഷണം ലോഡ് ചെയ്യുകയും ചെയ്യുന്നു.",
    architecturalCreed: "ഞങ്ങളുടെ വാസ്തുവിദ്യാ വിശ്വാസം",
    creedDesc1: "ആധുനിക ഡാറ്റാ വിളവെടുപ്പ് ബിസിനസ്സ് മോഡൽ ഞങ്ങൾ നിരസിക്കുന്നു. മിക്ക സാമ്പത്തിക ആപ്ലിക്കേഷനുകളും നിങ്ങളുടെ ഇടപാടുകൾ പാഴ്‌സ് ചെയ്യുകയും ക്രെഡിറ്റ് ബ്രോക്കർമാർക്ക് വിൽക്കുകയും ചെയ്യുന്നു. ലോഗ്ബുക്ക് പ്ലസ് ശക്തമായ ക്ലയൻ്റ്-സൈഡ് AES-256 എൻക്���ിപ്ഷൻ ഉപയോഗിക്കുന്നു, അതായത് നിങ്ങളുടെ ലോഗുകൾ എപ്പോഴെങ്കിലും സമന്വയിപ്പിക്കുന്നതിന് മുമ്പ് ഗണിതശാസ്ത്രപരമായി സുരക്ഷിതമാണ്.",
    creedDesc2: "നിങ്ങൾ പ്രതിദിന രസീതുകൾ സംഘടിപ്പിക്കുകയാണെങ്കിലും, പ്രതിവാര പ്രോജക്റ്റ് അക്കൗണ്ടുകൾ കൈകാര്യം ചെയ്യുകയാണെങ്കിലും അല്ലെങ്കിൽ പ്രതിമാസ പ്രസ്താവനകൾ എക്‌സ്‌പോർട്ടുചെയ്യുകയാണെങ്കിലും, നിങ്ങൾ സമ്പൂർണ്ണ ആജ്ഞയിലാണ്.",
    creedItem1: "സബ്-മില്ലിസെക്കൻഡ് പ്���തികരണ സമയങ്ങളുള്ള പ്രാദേശിക ഡാറ്റാബേസ്",
    creedItem2: "പൂർണ്ണമായും ഇഷ്ടാനുസൃതമാക്കാവുന്ന സ്റ്റോറേജ് പോളിസി ഘടനകൾ (പ്രതിദിനം, പ്രതിവാര, പ്രതിമാസ)",
    creedItem3: "തടസ്സമില്ലാത്ത ടോക്കൺ അടിസ്ഥാനമാക്കിയുള്ള അഡ്മിനിസ്ട്രേറ്റീവ് സമന്വയ നിരീക്ഷണം",
