    faqQ1: "ഡാറ്റ ശരിക്കും ക്ലയൻ്റ് സൈഡ് എൻക്രിപ്റ്റ് ചെയ്തതാണോ?",
    faqA1: "അതെ. ലോഗ്ബുക്ക് പ്ലസിനുള്ളിൽ ലോഗിൻ ചെയ്‌തിരിക്കുന്ന എല്ലാ ഡാറ്റയും കാഷെ ചെയ്‌തതിനോ സമന്വയിപ്പിക്കുന്നതിനോ മുമ്പായി AES-256 ബ്ലോക്ക് സൈഫർ ഉപയോഗിച്ച് പ്രാദേശികമായി എൻക്രിപ്റ്റ് ചെയ്‌തിരിക്കുന്നു. നിങ്ങളുടെ സ്വകാര്യ കീ പാസ്‌ഫ്രെയ്‌സ് ഇല്ലാതെ, ആർക്കും (ഞങ്ങളുടെ ഇൻഫ്രാസ്ട്രക്ചർ പ്രൊവൈഡർമാരോ ഡെവലപ്പർമാരോ ഉൾപ്പെടെ) നിങ്ങളുടെ റെക്കോർഡുകൾ വായിക്കാൻ കഴിയില്ല.",
    faqQ2: "ഞാൻ എൻ്റെ പ്രീമിയം സബ്‌സ്‌ക്രിപ്‌ഷൻ റദ്ദാക്കിയാൽ എന്ത് സംഭവിക്കും?",
    faqA2: "നിങ്ങളുടെ സബ്‌സ്‌ക്രിപ്‌ഷൻ റദ്ദാക്കുകയാണെങ്കിൽ, നിങ്ങളുടെ എല്ലാ എൻട്രികളിലേക്കും നിങ്ങൾക്ക് പ്രാദേശിക ആക്‌സസ് ഉണ്ടായിരിക്കും. നിങ്ങളുടെ ബില്ലിംഗ് സൈക്കിളിൻ്റെ അവസാനം വരെ ഞങ്ങളുടെ ക്ലൗഡ് വോൾട്ടിലെ നിങ്ങളുടെ ബാക്കപ്പുകൾ സജീവമായി തുടരും. കാലഹരണപ്പെട്ടതിന് ശേഷം, സുരക്ഷിതമായി ശുദ്ധീകരിക്കുന്നതിന് മുമ്പ് നിങ്ങളുടെ വോൾട്ട് ബാക്കപ്പ് ഡൗൺലോഡ് ചെയ്യുന്നതിന് ഞങ്ങൾ 30 ദിവസത്തെ ഗ്രേസ് പിരീഡ് നൽകുന്നു.",
    faqQ3: "സ്വയം ഹോസ്റ്റ് ചെയ്ത മാസ്റ്റർ ലൈസൻസ് എങ്ങനെയാണ് പ്രവർത്തിക്കുന്നത്?",
    faqA3: "നിങ്ങളുടെ സ്വന്തം സെർവർ ഹാർഡ്‌വെയറിൽ (ഉദാ. ഡോക്കർ, Node.js, WebDAV വഴി) ലോഗ്ബുക്ക് ബാക്കപ്പ് ടാർഗെറ്റ് കൺസോൾ പ്രവർത്തിപ്പിക്കുന്നതിന് സ്വയം-ഹോസ്‌റ്റഡ് മാസ്റ്റർ ലൈസൻസ് ശാശ്വതവും റോയൽറ്റി രഹിതവുമായ ഒരു കീ നൽകുന്നു. പൂർണ്ണമായ എൻക്രിപ്റ്റ് ചെയ്ത സമന്വയ പ്രവർത്തനം നിലനിർത്തിക്കൊണ്ട് ഇത് ഞങ്ങളുടെ ക്ലൗഡ് സെർവറുകളെ പൂർണ്ണമായും മറികടക്കുന്നു.",
    securityQuestion1: "നിങ്ങളുടെ ആദ്യത്തെ വളർത്തുമൃഗത്തിൻ്റെ പേരെന്തായിരുന്നു?",
