    bentoSecurityTitle: "શૂન્ય-જ્ઞાન સુરક્ષા",
    bentoSecurityDesc: "બધા બેકઅપ અપલોડ કરતા પહેલા તમારી SHA-256 હેશ કરેલી ખાનગી કી સાથે એન્ક્રિપ્ટેડ છે. અમારા સર્વર એડમિનિસ્ટ્રેટર્સ કોઈપણ સંજોગોમાં તમારી ફાઇલોને વાંચી, ડીકોડ અથવા વિશ્લેષણ કરી શકતા નથી.",
