    valueCloudTitle: "મેઘ સુરક્ષા",
    valueCloudDesc: "સીમલેસ બેકઅપ ઓટો-સિંક. અમારા ક્લાયંટ-સાઇડ એન્ક્રિપ્ટેડ ક્લાઉડ વૉલ્���્સ પર તમારા લૉગ્સનો બેકઅપ લો, ખાતરી કરો કે તમે સંપૂર્ણ કી નિયંત્રણ જાળવી રાખો છો.",
    valueLocalTitle: "સ્થાનિક-પ્રથમ ડેટા",
    valueLocalDesc: "તમારા મેટ્રિક્સ લોડ કરવા માટે ક્યારેય રિમોટ સર્વર પર આધાર રાખશો નહીં. બધા રેકોર્ડ્સ સ્થાનિક રીતે ઉપકરણ પર સંગ્રહિત થાય છે અને ઑફલાઇન પણ તરત જ લોડ થાય છે.",
    architecturalCreed: "અમારી આર્કિટેક્ચરલ પંથ",
    creedDesc1: "અમે આધુનિક ડેટા-હાર્વેસ્ટિંગ બિઝનેસ મોડલને નકારીએ છીએ. મોટાભાગની નાણાકીય એપ્લિકેશનો ક્રેડિટ બ્રોકર્સને તમારા વ્યવહારોનું વિશ્લેષણ અને વેચાણ કરે છે. લોગબુક પ્લસ મજબૂત ક્લાયંટ-સાઇડ AES-256 એન્ક્રિપ્શનનો ઉપયોગ કરે છે, એટલે કે તમારા લૉગ્સ ક્યારેય સિંક થાય તે પહેલાં ગાણિતિક રીતે સુરક્ષિત છે.",
    creedDesc2: "ભલે તમે દૈનિક રસીદોનું આયોજન કરી રહ્યાં હોવ, સાપ્તાહિક પ્રોજેક્ટ એકાઉન્ટ્સનું સંચાલન કરતા હોવ અથવા માસિક સ્ટેટમેન્ટની નિકાસ કરતા હોવ, તમે સંપૂર્ણ આદેશમાં છો.",
    creedItem1: "સબ-મિલિસેકન્ડ પ્રતિભાવ સમય સાથે સ્થાનિક ડેટાબેઝ",
