    faqA1: "હા. લોગબુક પ્લસની અંદર લોગ થયેલો તમામ ડેટા કેશ્ડ અથવા સિંક થાય તે પહેલા AES-256 બ્લોક સાઇફરનો ઉપયોગ કરીને સ્થાનિક રીતે એન્ક્રિપ્ટ કરવામાં આવે છે. તમારા ખાનગી કી પાસફ્રેઝ વિના, કોઈ (અમારા ઇન્ફ્રાસ્ટ્રક્ચર પ્રદાતાઓ અથવા વિકાસકર્તાઓ સહિત) તમારા રેકોર્ડ્સ વાંચી શકશે નહીં.",
    faqQ2: "જો હું મારું પ્રીમિયમ સબ્સ્ક્રિપ્શન રદ કરું તો શું થશે?",
    faqA2: "જો તમે તમારું સબ્સ્ક્રિપ્શન રદ કરો છો, તો તમે તમારી બધી એન્ટ્રીઓની સ્થાનિક ઍક્સેસ જાળવી રાખશો. અમારા ક્લાઉડ વૉલ્ટ પરના તમારા બેકઅપ તમારા બિલિંગ ચક્રના અંત સુધી સક્રિય રહેશે. સમાપ્તિ પછી, અમે તમારા વૉલ્ટ બેકઅપને સુરક્ષિત રીતે શુદ્ધ કરવામાં આવે તે પહેલાં તેને ડાઉનલોડ કરવા માટે 30-દિવસનો ગ્રેસ પીરિયડ પ્રદાન કરીએ છીએ.",
    faqQ3: "સ્વ-હોસ્ટેડ માસ્ટર લાઇસન્સ કેવી રીતે કાર્ય કરે છે?",
    faqA3: "સેલ્ફ-હોસ્ટેડ માસ્ટર લાઇસન્સ તમને તમારા પોતાના સર્વર હાર્ડવેર (દા.ત. ડોકર, Node.js, WebDAV દ્વારા) પર લોગબુક બેકઅપ લક્ષ્ય કન્સોલ ચલાવવા માટે કાયમી, રોયલ્ટી-મુક્ત કી આપે છે. સંપૂર્ણ એન્ક્રિપ્ટેડ સમન્વયન કાર્યક્ષમતા જાળવી રાખીને આ અમારા ક્લાઉડ સર્વરને સંપૂર્ણપણે બાયપાસ કરે છે.",
