    philosophySubtitle: "ਲੌਗਬੁੱਕ ਪਲੱਸ ਦੀ ਸਥਾਪਨਾ ਇੱਕ ਸਧਾਰਨ ਵਿਸ਼ਵਾਸ 'ਤੇ ਕੀਤੀ ਗਈ ਸੀ: ਤੁਹਾਨੂੰ ਆਧੁਨਿਕ ਬੈਕਅੱਪ ਦੀ ਸਹੂਲਤ ਲਈ ਆਪਣੀ ਵਿੱਤੀ ਗੋਪਨੀਯਤਾ ਦਾ ਵਪਾਰ ਨਹੀਂ ਕਰਨਾ ਚਾਹੀਦਾ। ਅਸੀਂ ਸੁੰਦਰ, ਸਥਾਨਕ-ਪਹਿਲੇ ਟੂਲ ਬਣਾਉਂਦੇ ਹਾਂ ਜੋ ਤੁਹਾਨੂੰ ਆਪਣੇ ਲੌਗਸ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਆਪਣੇ ਕੋਲ ਰੱਖਣ ਦੀ ਇਜਾਜ਼ਤ ਦਿੰਦੇ ਹਨ।",
