    faqQ1: "ਕੀ ਡੇਟਾ ਅਸਲ ਵਿੱਚ ਕਲਾਇੰਟ-ਸਾਈਡ ਐਨਕ੍ਰਿਪਟਡ ਹੈ?",
    faqA1: "ਹਾਂ। ਲੌਗਬੁੱਕ ਪਲੱਸ ਦੇ ਅੰਦਰ ਲੌਗ ਕੀਤੇ ਸਾਰੇ ਡੇਟਾ ਨੂੰ ਕੈਸ਼ ਜਾਂ ਸਿੰਕ ਕੀਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ AES-256 ਬਲਾਕ ਸਾਈਫਰ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਸਥਾਨਕ ਤੌਰ 'ਤੇ ਏਨਕ੍ਰਿਪਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਤੁਹਾਡੇ ਨਿੱਜੀ ਕੁੰਜੀ ਪਾਸਫ੍ਰੇਜ਼ ਤੋਂ ਬਿਨਾਂ, ਕੋਈ ਵੀ (ਸਾਡੇ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਪ੍ਰਦਾਤਾ ਜਾਂ ਵਿਕਾਸਕਰਤਾਵਾਂ ਸਮੇਤ) ਤੁਹਾਡੇ ਰਿਕਾਰਡਾਂ ਨੂੰ ਪੜ੍ਹ ਨਹੀਂ ਸਕਦਾ।",
    faqQ2: "ਕ�� ਹੁੰਦਾ ਹੈ ਜੇਕਰ ਮੈਂ ਆਪਣੀ ਪ੍ਰੀਮੀਅਮ ਗਾਹਕੀ ਨੂੰ ਰੱਦ ਕਰਦਾ ਹਾਂ?",
    faqA2: "ਜੇਕਰ ਤੁਸੀਂ ਆਪਣੀ ਗਾਹਕੀ ਨੂੰ ਰੱਦ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਆਪਣੀਆਂ ਸਾਰੀਆਂ ਐਂਟਰੀਆਂ ਤੱਕ ਸਥਾਨਕ ਪਹੁੰਚ ਬਰਕਰਾਰ ਰੱਖੋਗੇ। ਸਾਡੇ ਕਲਾਉਡ ਵਾਲਟ 'ਤੇ ਤੁਹਾਡੇ ਬੈਕਅੱਪ ਤੁਹਾਡੇ ਬਿਲਿੰਗ ਚੱਕਰ ਦੇ ਅੰਤ ਤੱਕ ਕਿਰਿਆਸ਼ੀਲ ਰਹਿਣਗੇ। ਮਿਆਦ ਪੁੱਗਣ ਤੋਂ ਬਾਅਦ, ਅਸੀਂ ਤੁਹਾਡੇ ਵਾਲਟ ਬੈਕਅੱਪ ਨੂੰ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਾਫ਼ ਕੀਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਇਸਨੂੰ ਡਾਊਨਲੋਡ ਕਰਨ ਲਈ 30-ਦਿਨਾਂ ਦੀ ਰਿਆਇਤ ਮਿਆਦ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ।",
    faqQ3: "ਸਵੈ-ਹੋਸਟਡ ਮਾਸਟਰ ਲਾਇਸੈਂਸ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ?",
    faqA3: "ਸਵੈ-ਹੋਸਟਡ ਮਾਸਟਰ ਲਾਇਸੈਂਸ ਤੁਹਾਨੂੰ ਤੁਹਾਡੇ ਆਪਣੇ ਸਰਵਰ ਹਾਰਡਵੇਅਰ (ਜਿਵੇਂ ਕਿ Docker, Node.js, WebDAV ਰਾਹੀਂ) 'ਤੇ ਲੌਗਬੁੱਕ ਬੈਕਅੱਪ ਟਾਰਗੇਟ ਕੰਸੋਲ ਨੂੰ ਚਲਾਉਣ ਲਈ ਇੱਕ ਸਦੀਵੀ, ਰਾਇਲਟੀ-ਮੁਕਤ ਕੁੰਜੀ ਦਿੰਦਾ ਹੈ। ਇਹ ਪੂਰੀ ਏਨਕ੍ਰਿਪਟਡ ਸਿੰਕ ਕਾਰਜਕੁਸ਼ਲਤਾ ਨੂੰ ਕਾਇਮ ਰੱਖਦੇ ਹੋਏ ਸਾਡੇ ਕਲਾਉਡ ਸਰਵਰਾਂ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਾਈਪਾਸ ਕਰਦਾ ਹੈ।",
