    faqA1: "ହଁ ଲଗବୁକ୍ ପ୍ଲସ୍ ଭିତରେ ଲଗ୍ ହୋଇଥିବା ସମସ୍ତ ତଥ୍ୟ କ୍ୟାଚ୍ କିମ୍ବା ସିଙ୍କ ହେବା ପୂର୍ବରୁ AES-256 ବ୍ଲକ୍ ସାଇଫର୍ ବ୍ୟବହାର କରି ସ୍ଥାନୀୟ ଭାବରେ ଏନକ୍ରିପ୍ଟ ହୋଇଥାଏ | ଆପଣଙ୍କର ବ୍ୟକ୍ତିଗତ କି ପାସଫ୍ରେଜ୍ ବିନା, କେହି କେହି (ଆମର ଭିତ୍ତିଭୂମି ପ୍ରଦାନକାରୀ କିମ୍ବା ବିକାଶକାରୀଙ୍କୁ ଅନ୍ତର୍ଭୁକ୍ତ କରି) ଆପଣଙ୍କର ରେକର୍ଡଗୁଡିକ ପ read ିପାରିବେ ନାହିଁ |",
