    bentoPrivacyDesc: "কোনো টেলিমেট্ৰি নাই। কোনো পটভূমি ট্ৰেকাৰ নাই। Logbook Plus এ আপোনাৰ ব্ৰাউজাৰ বা স্থানীয় কাৰ্য্যস্থানৰ ভিতৰত এটা স্থানীয় ডাটাবেইচত প্ৰত্যক্ষভাৱে সংৰক্ষণ কৰে। আমাৰ ক্লাউড চাৰ্ভাৰ বন্ধ হ'লেও আপোনাৰ চফ্টৱেৰটোৱে হুবহু একেদৰেই কাম কৰে।",
