    bentoRapidTitle: "ৰেপিড এণ্ট্ৰি ইঞ্জিন",
    bentoRapidDesc: "কিবৰ্ড চৰ্টকাটসমূহৰ সৈতে লেনদেন, লগসমূহ, আৰু শ্ৰেণীসমূহ ৰেকৰ্ড কৰক। Sub-10ms UI পেইন্ট গতি।",
    bentoQuickLog: "দ্ৰুত লগ ৰেকৰ্ড",
    bentoInsightsTitle: "ইন্টাৰেক্টিভ ইনচাইটছ",
    bentoInsightsDesc: "ৰেকৰ্ডসমূহ বাস্তৱ সময়ত ফিল্টাৰ কৰক, স্লাইচ কৰক, আৰু পৰ্যালোচনা কৰক। চাৰ্ট গণনাসমূহ ক্লাএন্ট-পক্ষত গণনা কৰা হয়, API ফেচসমূহ অবিহনে তাৎক্ষণিক পৰিকল্পনাসমূহ ঘূৰাই দিয়ে।",
    bentoSecurityTitle: "শূন্য-জ্ঞান সুৰক্ষা",
    bentoSecurityDesc: "আপলোড কৰাৰ আগতে সকলো বেকআপ আপোনাৰ SHA-256 হেশ্ব কৰা ব্যক্তিগত চাবিৰ সৈতে ইনক্ৰিপ্ট কৰা হয়। আমাৰ চাৰ্ভাৰ প্ৰশাসকসকলে কোনো পৰিস্থিতিত আপোনাৰ ফাইলসমূহ পঢ়িব, ডিকোড কৰিব, বা বিশ্লেষণ কৰিব নোৱাৰে।",
    valuePrivacyTitle: "নিৰপেক্ষ গোপনীয়তা",
    valuePrivacyDesc: "কোনো টেলিমেট্ৰি নাই, কোনো ট্ৰেকিং স্ক্ৰিপ্ট নাই, আৰু কোনো গোপন বিশ্লেষণাত্মক নিৰীক্ষণ নাই। আপুনি যি লগ ইন কৰে Logbook Plus আপোনাৰ আৰু আপোনাৰ ডিভাইচৰ মাজত থাকে।",
    valueCloudTitle: "ক্লাউড সুৰক্ষা",
    valueCloudDesc: "নিৰৱচ্ছিন্ন বেকআপ স্বয়ংক্ৰিয়-চিংক। আপোনাৰ লগসমূহ আমাৰ ক্লাএন্ট-পক্ষৰ এনক্ৰিপ্ট কৰা ক্লাউড ভল্টসমূহলে বেকআপ লওক, আপুনি নিৰপেক্ষ কি' নিয়ন্ত্ৰণ বজাই ৰখাটো সুনিশ্চিত কৰি।",
    valueLocalTitle: "স্থানীয়-প্ৰথম তথ্য",
    valueLocalDesc: "আপোনাৰ মেট্ৰিক্স লোড কৰিবলে কেতিয়াও দূৰৱৰ্তী চাৰ্ভাৰৰ ওপৰত নিৰ্ভৰ নকৰিব। সকলো ৰেকৰ্ড স্থানীয়ভাৱে অন-ডিভাইচ সংৰক্ষণ কৰা হয় আৰু অফলাইনতো তৎক্ষণাত লোড হয়।",
    architecturalCreed: "আমাৰ স্থাপত্যৰ বিশ্বাস",
    creedDesc1: "আমি আধুনিক ডাটা-হাৰ্ভেষ্টিং ব্যৱসায়িক মডেলক নাকচ কৰো। বেছিভাগ বিত্তীয় এপ্লিকেচনে আপোনাৰ লেনদেনসমূহ বিশ্লেষণ আৰু ক্ৰেডিট ব্ৰোকাৰসকলক বিক্ৰী কৰে। Logbook Plus এ শক্তিশালী ক্লাএন্ট-পক্ষৰ AES-256 ইনক্ৰিপষণ ব্যৱহাৰ কৰে, অৰ্থাৎ আপোনাৰ লগসমূহ কেতিয়াও সিঙ্ক কৰাৰ আগতে গাণিতিকভাৱে সুৰক্ষিত।",
    creedDesc2: "আপুনি দৈনিক ৰচিদসমূহ সংগঠিত কৰক, সাপ্তাহিক প্ৰকল্প একাউণ্টসমূহ পৰিচালনা কৰক, বা মাহেকীয়া বিবৃতিসমূহ ৰপ্তানি কৰক, আপুনি নিৰপেক্ষ আদেশত আছে।",
    creedItem1: "উপ-মিলিছেকেণ্ডৰ সঁহাৰিৰ সময়ৰ সৈতে স্থানীয় ডাটাবেছ",
